<section class="dashboard-content"><div class="dashboard-heading"><div class="eyebrow">فضای همکاری</div><h1>قراردادها و Milestoneها</h1><p class="muted">پیشرفت پروژه‌ها و تحویل‌ها را از یکجا مدیریت کنید.</p></div><?php if($m=Session::flash('success')): ?><div class="alert success">✅ <?=e($m)?></div><?php endif; ?><?php if($m=Session::flash('error')): ?><div class="alert error">⚠️ <?=e($m)?></div><?php endif; ?><?php foreach($contracts as $contract): $milestones=(new Contract())->milestones((int)$contract['id']); ?><section class="dash-card contract-card"><div class="card-title"><div><h2><?=e($contract['title'])?></h2><span>طرف همکاری: <?=e($contract['other_party']?:'کاربر')?></span></div><span class="status status-<?=e($contract['status'])?>"><?=e($contract['status'])?></span></div><div class="contract-meta"><strong><?=e($contract['total_amount'])?> دلار</strong><span>شروع: <?=e($contract['start_date']?:'تعیین نشده')?></span><span>پایان: <?=e($contract['end_date']?:'تعیین نشده')?></span></div><div class="milestone-list"><?php foreach($milestones as $milestone): ?><div class="milestone-row"><div><strong><?=e($milestone['title'])?></strong><small><?=e($milestone['description']?:'بدون توضیحات')?> · <?=e($milestone['amount'])?> دلار</small></div><span class="status status-<?=e($milestone['status'])?>"><?=e($milestone['status'])?></span><form method="post" action="<?=url('/contracts/milestones/status')?>"><?=csrf_field()?><input type="hidden" name="milestone_id" value="<?=e($milestone['id'])?>"><select name="status"><option value="submitted">ارسال برای بررسی</option><option value="revision">درخواست اصلاح</option><option value="approved">تأیید</option><option value="released">پرداخت‌شده</option></select><button class="button button-small" type="submit">ثبت</button></form></div><?php endforeach; ?><?php if(!$milestones): ?><p class="muted">هنوز Milestoneای ثبت نشده است.</p><?php endif; ?></div><form class="milestone-form" method="post" action="<?=url('/contracts/milestones')?>"><?=csrf_field()?><input type="hidden" name="contract_id" value="<?=e($contract['id'])?>"><input name="title" required placeholder="عنوان Milestone"><input type="number" name="amount" min="1" step="0.01" required placeholder="مبلغ دلار"><input type="date" name="due_date"><textarea name="description" rows="2" placeholder="شرح خروجی و تحویل..."></textarea><button class="button" type="submit">افزودن Milestone</button></form></section><?php endforeach; ?><?php if(!$contracts): ?><section class="dash-card empty-state">هنوز قراردادی برای شما ثبت نشده است.</section><?php endif; ?></section>